\copy (select distinct on (l.topic) l.topic as topik_id, lb.mapel, lb.tahap, l.topic_title as topik, l.bab, l.materi as bab_bermateri, l.bank as bab_berbank, l.lengkap as bab_lengkap, l.bank_tipis as bank_kurang_15, (select string_agg(distinct x.root, '; ') from leaf x where x.topic=l.topic) as dipakai_di_jalur from leaf l join lib lb on lb.topic=l.topic order by l.topic) to 'topik_dalam_jalur.csv' csv header
\copy (select lb.mapel, count(*) topik, sum(l.bab) bab, sum(l.materi) bab_bermateri, sum(l.bank) bab_berbank, sum(l.lengkap) bab_lengkap, sum(l.bab)-sum(l.lengkap) bab_perlu_dibuat, sum(l.bab)-sum(l.materi) perlu_materi, sum(l.bab)-sum(l.bank) perlu_bank from (select distinct on (topic) * from leaf) l join lib lb on lb.topic=l.topic group by lb.mapel order by sum(l.bab)-sum(l.lengkap) desc) to 'kebutuhan_per_mapel.csv' csv header
\copy (select distinct on (topic) root as jalur, bundle_jalur as lokasi, topic_title as topik from leaf where bab=0 order by topic, root) to 'topik_tanpa_bab.csv' csv header
\echo === M. kebutuhan per mapel (topik unik seluruh jalur) ===
select lb.mapel, count(*) topik, sum(l.bab) bab, sum(l.lengkap) lengkap, sum(l.bab)-sum(l.lengkap) perlu_dibuat, sum(l.bab)-sum(l.materi) perlu_materi, sum(l.materi)-sum(l.lengkap) hanya_perlu_bank
from (select distinct on (topic) * from leaf) l join lib lb on lb.topic=l.topic group by lb.mapel order by 5 desc;
